insert into public.products (id, name, description, price, categories, images, tags, featured, upsell, sort, i18n) values
  ('shawarma-pollo', 'Shawarma de pollo', 'Pan árabe, pollo, tomate, lechuga, cebolla, pepinillos y salsa de ajo.', 33000, array['shawarma']::text[], array['shawarma-pollo.webp']::text[], array[]::text[], true, false, 1, '{"en":{"name":"Chicken shawarma","description":"Pita bread, chicken, tomato, lettuce, onion, pickles and garlic sauce."},"de":{"name":"Hähnchen-Shawarma","description":"Fladenbrot, Hähnchen, Tomate, Salat, Zwiebel, Gewürzgurken und Knoblauchsoße."},"pt-BR":{"name":"Shawarma de frango","description":"Pão sírio, frango, tomate, alface, cebola, picles e molho de alho."},"it":{"name":"Shawarma di pollo","description":"Pane arabo, pollo, pomodoro, lattuga, cipolla, cetriolini e salsa all’aglio."},"ar":{"name":"شاورما دجاج","description":"خبز عربي، دجاج، بندورة، خس، بصل، مخلل وصلصة الثوم."},"ru":{"name":"Шаурма с курицей","description":"Арабская лепёшка, курица, помидор, салат, лук, маринованные огурцы и чесночный соус."},"uk":{"name":"Шаурма з куркою","description":"Арабський коржик, курка, помідор, салат, цибуля, мариновані огірки та часниковий соус."},"ar-LB":{"name":"شاورما دجاج","description":"خبز عربي، دجاج، بندورة، خس، بصل، مخلل وصلصة الثوم."}}'::jsonb),
  ('shawarma-mixto', 'Shawarma mixto', 'Pan árabe, pollo, carne, lechuga, tomate, pepinillos, cebolla y salsa de ajo.', 34000, array['shawarma']::text[], array['shawarma-mixto.webp']::text[], array[]::text[], true, false, 2, '{"en":{"name":"Mixed shawarma","description":"Pita bread, chicken, beef, lettuce, tomato, pickles, onion and garlic sauce."},"de":{"name":"Gemischtes Shawarma","description":"Fladenbrot, Hähnchen, Rind, Salat, Tomate, Gewürzgurken, Zwiebel und Knoblauchsoße."},"pt-BR":{"name":"Shawarma misto","description":"Pão sírio, frango, carne, alface, tomate, picles, cebola e molho de alho."},"it":{"name":"Shawarma misto","description":"Pane arabo, pollo, manzo, lattuga, pomodoro, cetriolini, cipolla e salsa all’aglio."},"ar":{"name":"شاورما مشكّلة","description":"خبز عربي، دجاج، لحم، خس، بندورة، مخلل، بصل وصلصة الثوم."},"ru":{"name":"Шаурма микс","description":"Арабская лепёшка, курица, говядина, салат, помидор, маринованные огурцы, лук и чесночный соус."},"uk":{"name":"Шаурма мікс","description":"Арабський коржик, курка, яловичина, салат, помідор, мариновані огірки, цибуля та часниковий соус."},"ar-LB":{"name":"شاورما مشكّلة","description":"خبز عربي، دجاج، لحم، خس، بندورة، مخلل، بصل وصلصة الثوم."}}'::jsonb),
  ('shawarma-cheddar', 'Shawarma de queso cheddar', 'Pan árabe, pollo, carne, queso cheddar y papas fritas (por dentro).', 40000, array['shawarma']::text[], array['shawarma-cheddar.webp']::text[], array[]::text[], true, false, 3, '{"en":{"name":"Cheddar cheese shawarma","description":"Pita bread, chicken, beef, cheddar cheese and French fries (inside)."},"de":{"name":"Cheddar-Shawarma","description":"Fladenbrot, Hähnchen, Rind, Cheddar und Pommes frites (innen)."},"pt-BR":{"name":"Shawarma de cheddar","description":"Pão sírio, frango, carne, queijo cheddar e batata frita (por dentro)."},"it":{"name":"Shawarma al cheddar","description":"Pane arabo, pollo, manzo, formaggio cheddar e patatine fritte (dentro)."},"ar":{"name":"شاورما بجبنة الشيدر","description":"خبز عربي، دجاج، لحم، جبنة شيدر وبطاطا مقلية (من الداخل)."},"ru":{"name":"Шаурма с чеддером","description":"Арабская лепёшка, курица, говядина, сыр чеддер и картофель фри (внутри)."},"uk":{"name":"Шаурма з чедером","description":"Арабський коржик, курка, яловичина, сир чедер і картопля фрі (всередині)."},"ar-LB":{"name":"شاورما بجبنة الشيدر","description":"خبز عربي، دجاج، لحم، جبنة شيدر وبطاطا مقلية (من الداخل)."}}'::jsonb),
  ('sandwich-falafel', 'Sándwich falafel (vegano)', 'Lechuga, tomate, cebolla y pepinillos con croquetas de garbanzo (falafel) y salsa tahine.', 27000, array['shawarma','vegetarianas']::text[], array['sandwich-falafel.webp']::text[], array['vegano']::text[], false, false, 4, '{"en":{"name":"Falafel sandwich (vegan)","description":"Lettuce, tomato, onion and pickles with chickpea fritters (falafel) and tahini sauce."},"de":{"name":"Falafel-Sandwich (vegan)","description":"Salat, Tomate, Zwiebel und Gewürzgurken mit Kichererbsenbällchen (Falafel) und Tahini-Soße."},"pt-BR":{"name":"Sanduíche de falafel (vegano)","description":"Alface, tomate, cebola e picles com bolinhos de grão-de-bico (falafel) e molho tahine."},"it":{"name":"Panino falafel (vegano)","description":"Lattuga, pomodoro, cipolla e cetriolini con polpette di ceci (falafel) e salsa tahina."},"ar":{"name":"سندويش فلافل (نباتي صرف)","description":"خس، بندورة، بصل ومخلل مع أقراص الحمص (فلافل) وصلصة الطحينة."},"ru":{"name":"Сэндвич с фалафелем (веган)","description":"Салат, помидор, лук и маринованные огурцы с нутовыми шариками (фалафель) и соусом тахини."},"uk":{"name":"Сендвіч з фалафелем (веган)","description":"Салат, помідор, цибуля та мариновані огірки з нутовими кульками (фалафель) і соусом тахіні."},"ar-LB":{"name":"سندويش فلافل (نباتي صرف)","description":"خس، بندورة، بصل ومخلل مع أقراص الحمص (فلافل) وصلصة الطحينة."}}'::jsonb),
  ('bowl-mixto', 'Bowl mixto', 'Base de lechuga, tomate, pepinillos, cebolla, cortes mixtos (carne y pollo), perejil y salsa de ajo.', 42500, array['bowls']::text[], array['bowl-mixto.webp']::text[], array[]::text[], true, false, 1, '{"en":{"name":"Mixed bowl","description":"Lettuce, tomato, pickles and onion base, mixed cuts (beef and chicken), parsley and garlic sauce."},"de":{"name":"Gemischte Bowl","description":"Basis aus Salat, Tomate, Gewürzgurken und Zwiebel, gemischtes Fleisch (Rind und Hähnchen), Petersilie und Knoblauchsoße."},"pt-BR":{"name":"Bowl misto","description":"Base de alface, tomate, picles e cebola, cortes mistos (carne e frango), salsinha e molho de alho."},"it":{"name":"Bowl misto","description":"Base di lattuga, pomodoro, cetriolini e cipolla, tagli misti (manzo e pollo), prezzemolo e salsa all’aglio."},"ar":{"name":"بول مشكّل","description":"قاعدة من الخس والبندورة والمخلل والبصل، قطع مشكّلة (لحم ودجاج)، بقدونس وصلصة الثوم."},"ru":{"name":"Боул микс","description":"Основа из салата, помидора, огурцов и лука, мясное ассорти (говядина и курица), петрушка и чесночный соус."},"uk":{"name":"Боул мікс","description":"Основа з салату, помідора, огірків і цибулі, м’ясне асорті (яловичина та курка), петрушка і часниковий соус."},"ar-LB":{"name":"بول مشكّل","description":"قاعدة من الخس والبندورة والمخلل والبصل، قطع مشكّلة (لحم ودجاج)، بقدونس وصلصة الثوم."}}'::jsonb),
  ('bowl-papas', 'Bowl papas', 'Base de lechuga, tomate, cebolla, pepinillos y cortes mixtos (carne de res y pechuga de pollo), salsa de ajo y perejil.', 49000, array['bowls']::text[], array['bowl-papas.webp']::text[], array[]::text[], false, false, 2, '{"en":{"name":"Fries bowl","description":"Lettuce, tomato, onion and pickles base with mixed cuts (beef and chicken breast), garlic sauce and parsley."},"de":{"name":"Pommes-Bowl","description":"Basis aus Salat, Tomate, Zwiebel und Gewürzgurken mit gemischtem Fleisch (Rind und Hähnchenbrust), Knoblauchsoße und Petersilie."},"pt-BR":{"name":"Bowl de batata","description":"Base de alface, tomate, cebola e picles com cortes mistos (carne e peito de frango), molho de alho e salsinha."},"it":{"name":"Bowl con patatine","description":"Base di lattuga, pomodoro, cipolla e cetriolini con tagli misti (manzo e petto di pollo), salsa all’aglio e prezzemolo."},"ar":{"name":"بول بطاطا","description":"قاعدة من الخس والبندورة والبصل والمخلل مع قطع مشكّلة (لحم بقري وصدر دجاج)، صلصة الثوم والبقدونس."},"ru":{"name":"Боул с картофелем","description":"Основа из салата, помидора, лука и огурцов с мясным ассорти (говядина и куриная грудка), чесночный соус и петрушка."},"uk":{"name":"Боул з картоплею","description":"Основа з салату, помідора, цибулі та огірків з м’ясним асорті (яловичина та куряче філе), часниковий соус і петрушка."},"ar-LB":{"name":"بول بطاطا","description":"قاعدة من الخس والبندورة والبصل والمخلل مع قطع مشكّلة (لحم بقري وصدر دجاج)، صلصة الثوم والبقدونس."}}'::jsonb),
  ('bowl-queso-cheddar', 'Bowl queso cheddar', 'Base de papas fritas, lechuga, tomate, cebolla y pepinillos, papas francesas, con cortes finos de shawarma y queso cheddar fundido.', 55000, array['bowls']::text[], array['bowl-queso-cheddar.webp']::text[], array[]::text[], true, false, 3, '{"en":{"name":"Cheddar cheese bowl","description":"French fries base, lettuce, tomato, onion and pickles, with thin shawarma cuts and melted cheddar cheese."},"de":{"name":"Cheddar-Bowl","description":"Pommes-Basis, Salat, Tomate, Zwiebel und Gewürzgurken mit feinen Shawarma-Streifen und geschmolzenem Cheddar."},"pt-BR":{"name":"Bowl de cheddar","description":"Base de batata frita, alface, tomate, cebola e picles, com tiras finas de shawarma e cheddar derretido."},"it":{"name":"Bowl al cheddar","description":"Base di patatine fritte, lattuga, pomodoro, cipolla e cetriolini, con sottili tagli di shawarma e cheddar fuso."},"ar":{"name":"بول جبنة شيدر","description":"قاعدة من البطاطا المقلية والخس والبندورة والبصل والمخلل، مع شرائح شاورما رفيعة وجبنة شيدر ذائبة."},"ru":{"name":"Боул с чеддером","description":"Основа из картофеля фри, салат, помидор, лук и огурцы, тонкие ломтики шаурмы и расплавленный чеддер."},"uk":{"name":"Боул з чедером","description":"Основа з картоплі фрі, салат, помідор, цибуля та огірки, тонкі шматочки шаурми та розплавлений чедер."},"ar-LB":{"name":"بول جبنة شيدر","description":"قاعدة من البطاطا المقلية والخس والبندورة والبصل والمخلل، مع شرائح شاورما رفيعة وجبنة شيدر ذائبة."}}'::jsonb),
  ('bandeja-x4', 'Bandeja x4', 'Incluye bebida 1.5L, 4 kibbeh, 4 falafel, 4 medios shawarma, papitas francesas, pan y salsas.', 195000, array['bandejas']::text[], array['bandeja-x4.webp']::text[], array['para compartir']::text[], true, false, 1, '{"en":{"name":"Platter for 4","description":"Includes a 1.5L drink, 4 kibbeh, 4 falafel, 4 half shawarmas, French fries, bread and sauces."},"de":{"name":"Platte für 4","description":"Inklusive 1,5-L-Getränk, 4 Kibbeh, 4 Falafel, 4 halbe Shawarmas, Pommes, Brot und Soßen."},"pt-BR":{"name":"Bandeja para 4","description":"Inclui bebida de 1,5 L, 4 quibes, 4 falafels, 4 meios shawarmas, batata frita, pão e molhos."},"it":{"name":"Vassoio per 4","description":"Include bibita da 1,5 L, 4 kibbeh, 4 falafel, 4 mezzi shawarma, patatine, pane e salse."},"ar":{"name":"صينية لأربعة أشخاص","description":"تشمل مشروب 1.5 لتر، 4 كبة، 4 فلافل، 4 أنصاف شاورما، بطاطا مقلية، خبز وصلصات."},"ru":{"name":"Сет на 4 персоны","description":"Включает напиток 1,5 л, 4 киббе, 4 фалафеля, 4 половинки шаурмы, картофель фри, хлеб и соусы."},"uk":{"name":"Сет на 4 персони","description":"Включає напій 1,5 л, 4 кіббе, 4 фалафелі, 4 половинки шаурми, картоплю фрі, хліб і соуси."},"ar-LB":{"name":"صينية لأربعة أشخاص","description":"تشمل مشروب 1.5 لتر، 4 كبة، 4 فلافل، 4 أنصاف شاورما، بطاطا مقلية، خبز وصلصات."}}'::jsonb),
  ('plato-mixto-especial', 'Plato mixto especial', '1/2 shawarma, 2 kibbeh, tabbouleh, 2 falafel, 2 pan mini árabe y hummus (crema de garbanzo).', 58000, array['bandejas']::text[], array['plato-mixto-especial.webp']::text[], array[]::text[], true, false, 2, '{"en":{"name":"Special mixed plate","description":"1/2 shawarma, 2 kibbeh, tabbouleh, 2 falafel, 2 mini pita breads and hummus (chickpea cream)."},"de":{"name":"Spezialteller gemischt","description":"1/2 Shawarma, 2 Kibbeh, Taboulé, 2 Falafel, 2 Mini-Fladenbrote und Hummus (Kichererbsencreme)."},"pt-BR":{"name":"Prato misto especial","description":"1/2 shawarma, 2 quibes, tabule, 2 falafels, 2 mini pães sírios e homus (creme de grão-de-bico)."},"it":{"name":"Piatto misto speciale","description":"1/2 shawarma, 2 kibbeh, tabbouleh, 2 falafel, 2 mini pani arabi e hummus (crema di ceci)."},"ar":{"name":"صحن مشكّل خاص","description":"نصف شاورما، 2 كبة، تبولة، 2 فلافل، 2 خبز عربي صغير وحمص."},"ru":{"name":"Фирменное ассорти","description":"1/2 шаурмы, 2 киббе, табуле, 2 фалафеля, 2 мини-лепёшки и хумус (крем из нута)."},"uk":{"name":"Фірмове асорті","description":"1/2 шаурми, 2 кіббе, табуле, 2 фалафелі, 2 міні-коржики та хумус (крем з нуту)."},"ar-LB":{"name":"صحن مشكّل خاص","description":"نصف شاورما، 2 كبة، تبولة، 2 فلافل، 2 خبز عربي صغير وحمص."}}'::jsonb),
  ('hummus', 'Hummus', 'Tahini con garbanzos y pan mini.', 25000, array['bandejas','vegetarianas']::text[], array['hummus.webp']::text[], array['vegetariano']::text[], false, false, 3, '{"en":{"name":"Hummus","description":"Tahini with chickpeas and mini pita bread."},"de":{"name":"Hummus","description":"Tahini mit Kichererbsen und Mini-Fladenbrot."},"pt-BR":{"name":"Homus","description":"Tahine com grão-de-bico e mini pão sírio."},"it":{"name":"Hummus","description":"Tahina con ceci e mini pane arabo."},"ar":{"name":"حمص","description":"طحينة مع الحمص وخبز عربي صغير."},"ru":{"name":"Хумус","description":"Тахини с нутом и мини-лепёшками."},"uk":{"name":"Хумус","description":"Тахіні з нутом і міні-коржиками."},"ar-LB":{"name":"حمص","description":"طحينة مع الحمص وخبز عربي صغير."}}'::jsonb),
  ('tabbuleh', 'Tabbuleh', 'Ensalada a base de perejil, tomate, cebolla y trigo.', 22000, array['bandejas','vegetarianas']::text[], array['tabbuleh.webp']::text[], array['vegetariano']::text[], false, false, 4, '{"en":{"name":"Tabbouleh","description":"Salad made with parsley, tomato, onion and bulgur wheat."},"de":{"name":"Taboulé","description":"Salat aus Petersilie, Tomate, Zwiebel und Bulgur."},"pt-BR":{"name":"Tabule","description":"Salada de salsinha, tomate, cebola e trigo."},"it":{"name":"Tabbouleh","description":"Insalata di prezzemolo, pomodoro, cipolla e bulgur."},"ar":{"name":"تبولة","description":"سلطة من البقدونس والبندورة والبصل والبرغل."},"ru":{"name":"Табуле","description":"Салат из петрушки, помидоров, лука и булгура."},"uk":{"name":"Табуле","description":"Салат з петрушки, помідорів, цибулі та булгуру."},"ar-LB":{"name":"تبولة","description":"سلطة من البقدونس والبندورة والبصل والبرغل."}}'::jsonb),
  ('combo-falafel-x3', 'Combo falafel x3', '3 falafel (croqueta de garbanzos), pan árabe y hummus.', 15000, array['entradas']::text[], array['combo-falafel-x3.webp']::text[], array[]::text[], false, true, 1, '{"en":{"name":"Falafel combo x3","description":"3 falafel (chickpea fritters), pita bread and hummus."},"de":{"name":"Falafel-Combo x3","description":"3 Falafel (Kichererbsenbällchen), Fladenbrot und Hummus."},"pt-BR":{"name":"Combo falafel x3","description":"3 falafels (bolinhos de grão-de-bico), pão sírio e homus."},"it":{"name":"Combo falafel x3","description":"3 falafel (polpette di ceci), pane arabo e hummus."},"ar":{"name":"وجبة فلافل ×3","description":"3 فلافل (أقراص الحمص)، خبز عربي وحمص."},"ru":{"name":"Комбо фалафель x3","description":"3 фалафеля (нутовые шарики), арабская лепёшка и хумус."},"uk":{"name":"Комбо фалафель x3","description":"3 фалафелі (нутові кульки), арабський коржик і хумус."},"ar-LB":{"name":"وجبة فلافل ×3","description":"3 فلافل (أقراص الحمص)، خبز عربي وحمص."}}'::jsonb),
